window.INTERVIEW_DATA = {"source": "https://tempo.nhohoai.vn/cau-hoi-phong-van", "credit": "Nội dung mẫu tạm lấy từ Tempo (tempo.nhohoai.vn) — sẽ soạn lại sau.", "lessons": [{"id": "le-1", "num": 1, "title": "Tell me about yourself", "questions": [{"slug": "can-you-tell-me-a-bit-about-yourself", "q_en": "Can you tell me a bit about yourself?", "q_vi": "Bạn có thể chia sẻ đôi chút về bản thân không?", "lines": [{"en": "I'm a software engineer with about four years of experience, mostly in backend development.", "vi": "Tôi là kỹ sư phần mềm với khoảng bốn năm kinh nghiệm, chủ yếu về phát triển backend."}, {"en": "I studied Information Technology at university and started my career at a small startup.", "vi": "Tôi học Công nghệ Thông tin ở đại học và bắt đầu sự nghiệp tại một startup nhỏ."}, {"en": "These days, I focus on building APIs and improving system performance.", "vi": "Hiện tại tôi tập trung xây dựng API và cải thiện hiệu năng hệ thống."}]}, {"slug": "what-do-you-do-in-your-current-role", "q_en": "What do you do in your current role?", "q_vi": "Công việc hiện tại của bạn là gì?", "lines": [{"en": "I design and maintain backend services for our main product.", "vi": "Tôi thiết kế và duy trì các dịch vụ backend cho sản phẩm chính của công ty."}, {"en": "I also work closely with the frontend team to keep our APIs easy to use.", "vi": "Tôi cũng làm việc chặt chẽ với team frontend để giữ API dễ sử dụng."}, {"en": "On top of that, I review code and mentor a couple of junior developers.", "vi": "Ngoài ra, tôi review code và mentor vài bạn developer junior."}]}, {"slug": "what-are-you-looking-for-in-your-next-job", "q_en": "What are you looking for in your next job?", "q_vi": "Bạn đang tìm kiếm điều gì ở công việc tiếp theo?", "lines": [{"en": "I'm hoping to keep growing technically, especially around distributed systems.", "vi": "Tôi mong muốn tiếp tục phát triển kỹ thuật, đặc biệt là về hệ thống phân tán."}, {"en": "I also want a team with a strong engineering culture and good mentorship.", "vi": "Tôi cũng muốn một team có văn hóa kỹ thuật tốt và được mentor đàng hoàng."}, {"en": "Interesting problems matter more to me than the job title.", "vi": "Những bài toán thú vị quan trọng với tôi hơn là chức danh công việc."}]}, {"slug": "why-are-you-thinking-about-leaving-your-current-company", "q_en": "Why are you thinking about leaving your current company?", "q_vi": "Vì sao bạn đang nghĩ đến việc rời công ty hiện tại?", "lines": [{"en": "The company is doing fine, but I've reached a point where I'm not learning much anymore.", "vi": "Công ty vẫn đang ổn, nhưng tôi đã đến giai đoạn không học thêm được nhiều nữa."}, {"en": "I want a bigger challenge and more room to grow.", "vi": "Tôi muốn một thử thách lớn hơn và nhiều không gian để phát triển."}, {"en": "It's not about anything negative, just timing.", "vi": "Không phải vì điều gì tiêu cực, chỉ là vấn đề thời điểm."}]}, {"slug": "how-would-your-colleagues-describe-you", "q_en": "How would your colleagues describe you?", "q_vi": "Đồng nghiệp sẽ miêu tả bạn như thế nào?", "lines": [{"en": "I think they'd say I'm reliable and easy to work with.", "vi": "Tôi nghĩ họ sẽ nói tôi là người đáng tin cậy và dễ hợp tác."}, {"en": "A few might mention that I ask a lot of questions before starting a task.", "vi": "Vài người có thể nhắc rằng tôi hay hỏi nhiều trước khi bắt đầu một việc."}, {"en": "That's actually intentional, since it saves time later on.", "vi": "Đó thực ra là chủ đích, vì nó giúp tiết kiệm thời gian về sau."}]}]}, {"id": "le-2", "num": 2, "title": "Why do you want to work here?", "questions": [{"slug": "why-do-you-want-to-work-at-our-company", "q_en": "Why do you want to work at our company?", "q_vi": "Vì sao bạn muốn làm việc tại công ty chúng tôi?", "lines": [{"en": "I've been following your product for a while, and I like how fast the engineering team ships features.", "vi": "Tôi đã theo dõi sản phẩm của công ty một thời gian, và tôi thích cách team engineering ship tính năng nhanh."}, {"en": "Your recent move into cloud infrastructure also matches what I want to work on next.", "vi": "Việc công ty gần đây chuyển hướng sang cloud infrastructure cũng khớp với điều tôi muốn làm tiếp theo."}, {"en": "Beyond the tech, I've heard good things about the team culture here.", "vi": "Ngoài mặt kỹ thuật, tôi cũng nghe nhiều điều tốt về văn hóa team ở đây."}]}, {"slug": "what-do-you-know-about-our-product", "q_en": "What do you know about our product?", "q_vi": "Bạn biết gì về sản phẩm của chúng tôi?", "lines": [{"en": "From what I understand, it's a platform that helps businesses manage their data pipelines.", "vi": "Theo tôi hiểu, đây là một nền tảng giúp doanh nghiệp quản lý data pipeline của họ."}, {"en": "I tried the free version last week to get a feel for the user experience.", "vi": "Tôi đã thử bản miễn phí tuần trước để trải nghiệm thử."}, {"en": "I was impressed by how simple the onboarding flow was.", "vi": "Tôi khá ấn tượng vì luồng onboarding đơn giản đến vậy."}]}, {"slug": "how-does-this-role-fit-your-career-goals", "q_en": "How does this role fit your career goals?", "q_vi": "Vị trí này phù hợp với mục tiêu sự nghiệp của bạn thế nào?", "lines": [{"en": "This position would let me move from a pure backend role into more of a platform engineering role.", "vi": "Vị trí này sẽ giúp tôi chuyển từ một vai trò backend thuần túy sang vai trò platform engineering nhiều hơn."}, {"en": "That's exactly the direction I want to grow in over the next few years.", "vi": "Đó chính xác là hướng tôi muốn phát triển trong vài năm tới."}, {"en": "It also gives me a chance to work with a much larger user base.", "vi": "Nó cũng cho tôi cơ hội làm việc với một lượng người dùng lớn hơn nhiều."}]}, {"slug": "what-excites-you-most-about-this-position", "q_en": "What excites you most about this position?", "q_vi": "Điều gì khiến bạn hào hứng nhất với vị trí này?", "lines": [{"en": "Honestly, the scale excites me the most.", "vi": "Thật ra, quy mô hệ thống khiến tôi hào hứng nhất."}, {"en": "I've never worked on a system that handles this many requests per second.", "vi": "Tôi chưa từng làm việc trên một hệ thống xử lý lượng request mỗi giây lớn như vậy."}, {"en": "I'm curious to see how the architecture holds up under that kind of load.", "vi": "Tôi rất muốn xem kiến trúc hệ thống sẽ chịu tải như thế nào."}]}, {"slug": "is-there-anything-that-worries-you-about-this-role", "q_en": "Is there anything that worries you about this role?", "q_vi": "Có điều gì khiến bạn lo lắng về vị trí này không?", "lines": [{"en": "Not really a worry, but I know there will be a learning curve with your tech stack.", "vi": "Không hẳn là lo lắng, nhưng tôi biết sẽ có một khoảng học hỏi với tech stack của công ty."}, {"en": "I haven't used Kubernetes in production before, only in personal projects.", "vi": "Tôi chưa dùng Kubernetes ở production, chỉ mới dùng trong các project cá nhân."}, {"en": "I'm confident I can pick it up quickly, though.", "vi": "Nhưng tôi tin là mình sẽ bắt kịp nhanh."}]}]}, {"id": "le-3", "num": 3, "title": "Describe a challenging bug you fixed", "questions": [{"slug": "can-you-describe-a-challenging-bug-you-fixed-recently", "q_en": "Can you describe a challenging bug you fixed recently?", "q_vi": "Bạn có thể kể về một bug khó mà bạn vừa sửa gần đây không?", "lines": [{"en": "Sure, we had an issue where orders were occasionally being processed twice.", "vi": "Được, chúng tôi từng gặp vấn đề đơn hàng đôi lúc bị xử lý hai lần."}, {"en": "It only happened under high traffic, so it was hard to reproduce at first.", "vi": "Nó chỉ xảy ra khi traffic cao, nên ban đầu rất khó tái hiện."}, {"en": "It took me almost three days to track down the root cause.", "vi": "Tôi mất gần ba ngày để tìm ra nguyên nhân gốc."}]}, {"slug": "how-did-you-find-the-root-cause", "q_en": "How did you find the root cause?", "q_vi": "Bạn đã tìm ra nguyên nhân gốc như thế nào?", "lines": [{"en": "I started by adding more detailed logging around the payment service.", "vi": "Tôi bắt đầu bằng cách thêm log chi tiết hơn quanh payment service."}, {"en": "After a while, I noticed the bug only appeared when two requests arrived within the same second.", "vi": "Sau một thời gian, tôi nhận ra bug chỉ xuất hiện khi hai request đến trong cùng một giây."}, {"en": "That's when I realized we were missing a proper idempotency check.", "vi": "Lúc đó tôi nhận ra chúng tôi thiếu một cơ chế kiểm tra idempotency đúng chuẩn."}]}, {"slug": "what-did-you-do-to-fix-it", "q_en": "What did you do to fix it?", "q_vi": "Bạn đã làm gì để sửa nó?", "lines": [{"en": "I added an idempotency key to every order request.", "vi": "Tôi thêm một idempotency key vào mỗi request đặt hàng."}, {"en": "This way, the server can recognize duplicate requests and safely ignore them.", "vi": "Nhờ vậy server có thể nhận ra request trùng và bỏ qua an toàn."}, {"en": "We also added a test case to make sure this doesn't happen again.", "vi": "Chúng tôi cũng thêm test case để đảm bảo việc này không lặp lại."}]}, {"slug": "did-you-face-any-pressure-while-fixing-it", "q_en": "Did you face any pressure while fixing it?", "q_vi": "Bạn có gặp áp lực gì khi sửa lỗi này không?", "lines": [{"en": "Yes, customers were being charged twice, so the pressure was real.", "vi": "Có, khách hàng đang bị trừ tiền hai lần, nên áp lực là thật."}, {"en": "I had to update my manager every few hours on the progress.", "vi": "Tôi phải cập nhật tiến độ cho quản lý mỗi vài giờ."}, {"en": "That pressure actually helped me stay focused on the problem.", "vi": "Áp lực đó thực ra giúp tôi tập trung hơn vào vấn đề."}]}, {"slug": "what-did-you-learn-from-that-experience", "q_en": "What did you learn from that experience?", "q_vi": "Bạn học được gì từ trải nghiệm đó?", "lines": [{"en": "I learned that logging is often more valuable than guessing.", "vi": "Tôi học được rằng logging thường có giá trị hơn việc đoán mò."}, {"en": "I also learned to think more carefully about idempotency early in the design process.", "vi": "Tôi cũng học cách suy nghĩ kỹ hơn về idempotency ngay từ giai đoạn thiết kế."}, {"en": "Now I try to ask about duplicate requests whenever I design a new API.", "vi": "Giờ tôi luôn đặt câu hỏi về request trùng mỗi khi thiết kế một API mới."}]}]}, {"id": "le-4", "num": 4, "title": "How do you handle tight deadlines?", "questions": [{"slug": "how-do-you-usually-handle-tight-deadlines", "q_en": "How do you usually handle tight deadlines?", "q_vi": "Bạn thường xử lý deadline gấp như thế nào?", "lines": [{"en": "First, I break the task down into smaller pieces so I can see what's realistic.", "vi": "Đầu tiên, tôi chia nhỏ công việc để thấy rõ điều gì thực tế có thể làm được."}, {"en": "Then I talk to my manager early if I think the deadline isn't achievable.", "vi": "Sau đó tôi nói sớm với quản lý nếu tôi thấy deadline khó khả thi."}, {"en": "I'd rather raise a concern early than surprise everyone at the last minute.", "vi": "Tôi thích nêu vấn đề sớm hơn là để mọi người bất ngờ vào giờ chót."}]}, {"slug": "can-you-give-an-example-of-a-tight-deadline-you-faced", "q_en": "Can you give an example of a tight deadline you faced?", "q_vi": "Bạn có thể cho ví dụ về một deadline gấp bạn từng gặp không?", "lines": [{"en": "Last year, we had to launch a new feature before a big client demo.", "vi": "Năm ngoái, chúng tôi phải ra mắt một tính năng mới trước buổi demo lớn với khách hàng."}, {"en": "We only had about a week, which was tighter than usual.", "vi": "Chúng tôi chỉ có khoảng một tuần, gấp hơn bình thường."}, {"en": "I ended up cutting a few non-essential parts of the feature to make it work.", "vi": "Cuối cùng tôi phải cắt bớt vài phần không thiết yếu của tính năng để kịp."}]}, {"slug": "how-do-you-decide-what-to-cut-when-time-is-short", "q_en": "How do you decide what to cut when time is short?", "q_vi": "Bạn quyết định cắt bớt phần nào khi thời gian gấp?", "lines": [{"en": "I usually focus on what the client actually needs to see working.", "vi": "Tôi thường tập trung vào điều khách hàng thực sự cần thấy hoạt động."}, {"en": "Anything that's just nice to have gets pushed to a later release.", "vi": "Những gì chỉ là \"có thì tốt\" sẽ được dời sang bản phát hành sau."}, {"en": "I always double-check this decision with my manager first.", "vi": "Tôi luôn kiểm tra lại quyết định này với quản lý trước."}]}, {"slug": "have-you-ever-missed-a-deadline", "q_en": "Have you ever missed a deadline?", "q_vi": "Bạn đã từng trễ deadline chưa?", "lines": [{"en": "Yes, once I underestimated how long a database migration would take.", "vi": "Có, một lần tôi đánh giá thấp thời gian cần để migrate database."}, {"en": "It ended up taking two extra days because of unexpected data issues.", "vi": "Cuối cùng nó mất thêm hai ngày vì các vấn đề dữ liệu phát sinh."}, {"en": "Since then, I always add some buffer time when I estimate migrations.", "vi": "Từ đó tôi luôn thêm thời gian dự phòng khi ước lượng việc migrate."}]}, {"slug": "how-do-you-stay-calm-under-pressure", "q_en": "How do you stay calm under pressure?", "q_vi": "Bạn giữ bình tĩnh dưới áp lực như thế nào?", "lines": [{"en": "Honestly, I try to focus on one task at a time instead of thinking about everything at once.", "vi": "Thật ra tôi cố tập trung vào một việc một lúc, thay vì nghĩ về mọi thứ cùng lúc."}, {"en": "Taking a short walk also helps me reset when I feel stuck.", "vi": "Đi bộ một chút cũng giúp tôi lấy lại tinh thần khi cảm thấy bế tắc."}, {"en": "I've found that panicking never actually makes the work go faster.", "vi": "Tôi nhận ra hoảng loạn chưa bao giờ giúp công việc nhanh hơn."}]}]}, {"id": "le-5", "num": 5, "title": "Tell me about a disagreement with a teammate", "questions": [{"slug": "tell-me-about-a-time-you-disagreed-with-a-teammate", "q_en": "Tell me about a time you disagreed with a teammate.", "q_vi": "Kể về một lần bạn bất đồng ý kiến với đồng nghiệp.", "lines": [{"en": "During a code review, a teammate and I disagreed about how to structure a new service.", "vi": "Trong một buổi code review, tôi và một đồng nghiệp bất đồng về cách thiết kế cấu trúc cho một service mới."}, {"en": "He wanted to keep everything in one big service, while I preferred splitting it into smaller parts.", "vi": "Anh ấy muốn giữ mọi thứ trong một service lớn, còn tôi muốn tách thành các phần nhỏ hơn."}, {"en": "We went back and forth for a while before finding a middle ground.", "vi": "Chúng tôi tranh luận qua lại một lúc trước khi tìm được điểm chung."}]}, {"slug": "how-did-you-handle-the-disagreement", "q_en": "How did you handle the disagreement?", "q_vi": "Bạn đã xử lý bất đồng đó như thế nào?", "lines": [{"en": "I asked him to walk me through his reasoning instead of just pushing my own idea.", "vi": "Tôi nhờ anh ấy giải thích rõ lý do của mình, thay vì chỉ khăng khăng bảo vệ ý kiến của tôi."}, {"en": "It turned out he was worried about the extra complexity of managing multiple services.", "vi": "Hóa ra anh ấy lo ngại về độ phức tạp phát sinh khi quản lý nhiều service."}, {"en": "Once I understood that, it was easier to find a solution we both agreed on.", "vi": "Khi hiểu điều đó, việc tìm ra giải pháp cả hai đều đồng ý trở nên dễ hơn."}]}, {"slug": "what-was-the-outcome", "q_en": "What was the outcome?", "q_vi": "Kết quả cuối cùng là gì?", "lines": [{"en": "We decided to split the service into two parts instead of five, which was a compromise.", "vi": "Chúng tôi quyết định tách service thành hai phần thay vì năm, đó là một sự thỏa hiệp."}, {"en": "It kept things simple enough for him while still solving my performance concerns.", "vi": "Cách này vẫn đủ đơn giản cho anh ấy, mà vẫn giải quyết được lo ngại về hiệu năng của tôi."}, {"en": "Looking back, the final design was actually better than either of our original ideas.", "vi": "Nhìn lại, thiết kế cuối cùng thực ra tốt hơn cả hai ý tưởng ban đầu của chúng tôi."}]}, {"slug": "how-do-you-usually-give-feedback-during-code-review", "q_en": "How do you usually give feedback during code review?", "q_vi": "Bạn thường góp ý như thế nào khi code review?", "lines": [{"en": "I try to explain the reason behind my comment, not just point out the problem.", "vi": "Tôi cố giải thích lý do phía sau nhận xét của mình, không chỉ chỉ ra vấn đề."}, {"en": "I also try to ask questions instead of giving direct orders.", "vi": "Tôi cũng cố đặt câu hỏi thay vì đưa ra yêu cầu trực tiếp."}, {"en": "That way, it feels more like a discussion than a criticism.", "vi": "Như vậy nó giống một cuộc trao đổi hơn là một lời chê trách."}]}, {"slug": "how-do-you-receive-feedback-on-your-own-code", "q_en": "How do you receive feedback on your own code?", "q_vi": "Bạn tiếp nhận góp ý về code của mình như thế nào?", "lines": [{"en": "I try not to take it personally, even if the comment feels blunt.", "vi": "Tôi cố không xem đó là chuyện cá nhân, dù nhận xét có nghe hơi thẳng."}, {"en": "I usually ask for an example if I don't understand the suggestion.", "vi": "Tôi thường hỏi thêm ví dụ nếu chưa hiểu rõ góp ý."}, {"en": "In the end, most feedback has made my code better.", "vi": "Cuối cùng, hầu hết góp ý đều giúp code của tôi tốt hơn."}]}]}, {"id": "le-6", "num": 6, "title": "How do you keep your skills up to date?", "questions": [{"slug": "how-do-you-keep-your-technical-skills-up-to-date", "q_en": "How do you keep your technical skills up to date?", "q_vi": "Bạn cập nhật kỹ năng kỹ thuật của mình như thế nào?", "lines": [{"en": "I read engineering blogs from companies I admire, usually once or twice a week.", "vi": "Tôi đọc blog kỹ thuật từ các công ty tôi ngưỡng mộ, thường một hai lần mỗi tuần."}, {"en": "I also try to build small side projects with tools I haven't used before.", "vi": "Tôi cũng cố làm các side project nhỏ với những công cụ mình chưa từng dùng."}, {"en": "Podcasts are useful too, especially during my commute.", "vi": "Podcast cũng hữu ích, đặc biệt là lúc tôi di chuyển."}]}, {"slug": "what-resources-do-you-use-to-learn-new-technologies", "q_en": "What resources do you use to learn new technologies?", "q_vi": "Bạn dùng nguồn nào để học công nghệ mới?", "lines": [{"en": "Official documentation is usually my first stop when I want to learn something properly.", "vi": "Tài liệu chính thức thường là nơi tôi tìm đến đầu tiên khi muốn học nghiêm túc."}, {"en": "After that, I look for video tutorials if the topic is more visual.", "vi": "Sau đó tôi tìm video hướng dẫn nếu chủ đề thiên về hình ảnh."}, {"en": "Online courses are helpful when I need a structured path.", "vi": "Khóa học online hữu ích khi tôi cần một lộ trình rõ ràng."}]}, {"slug": "can-you-give-an-example-of-something-new-you-learned", "q_en": "Can you give an example of something new you learned recently?", "q_vi": "Bạn có thể cho ví dụ về điều mới bạn vừa học gần đây không?", "lines": [{"en": "I recently learned how to use container orchestration tools for a personal project.", "vi": "Gần đây tôi học cách dùng công cụ container orchestration cho một project cá nhân."}, {"en": "It took some time to understand the networking part.", "vi": "Tôi mất một thời gian để hiểu phần networking."}, {"en": "Now I feel comfortable enough to bring it up in technical discussions.", "vi": "Giờ tôi đã tự tin đủ để nói về nó trong các buổi thảo luận kỹ thuật."}]}, {"slug": "how-do-you-share-what-you-learn-with-your-team", "q_en": "How do you share what you learn with your team?", "q_vi": "Bạn chia sẻ điều mình học được với team như thế nào?", "lines": [{"en": "I usually write a short summary and share it in our team channel.", "vi": "Tôi thường viết một bản tóm tắt ngắn và chia sẻ trong channel của team."}, {"en": "Sometimes I present a quick demo during our weekly sync.", "vi": "Đôi khi tôi demo nhanh trong buổi sync hàng tuần."}, {"en": "This helps the whole team stay updated without everyone doing the research alone.", "vi": "Điều này giúp cả team cập nhật thông tin mà không cần ai cũng phải tự tìm hiểu riêng."}]}, {"slug": "do-you-have-a-specific-technology-you-want-to-learn-next", "q_en": "Do you have a specific technology you want to learn next?", "q_vi": "Bạn có công nghệ cụ thể nào muốn học tiếp theo không?", "lines": [{"en": "Yes, I want to go deeper into system design and scalability patterns.", "vi": "Có, tôi muốn tìm hiểu sâu hơn về system design và các pattern về khả năng mở rộng."}, {"en": "It's an area I only understand at a surface level right now.", "vi": "Đây là mảng tôi mới chỉ hiểu ở mức cơ bản."}, {"en": "I think it will help me make better architecture decisions in the future.", "vi": "Tôi nghĩ nó sẽ giúp tôi đưa ra quyết định kiến trúc tốt hơn trong tương lai."}]}]}, {"id": "le-7", "num": 7, "title": "What's your ideal team and work environment?", "questions": [{"slug": "what-does-your-ideal-team-look-like", "q_en": "What does your ideal team look like?", "q_vi": "Team lý tưởng của bạn trông như thế nào?", "lines": [{"en": "I like working with people who are open about problems instead of hiding them.", "vi": "Tôi thích làm việc với những người thẳng thắn về vấn đề, thay vì che giấu."}, {"en": "A good mix of experience levels also helps, since juniors and seniors can learn from each other.", "vi": "Sự kết hợp tốt giữa các cấp độ kinh nghiệm cũng hữu ích, vì junior và senior có thể học hỏi lẫn nhau."}, {"en": "Clear communication matters more to me than everyone being a genius.", "vi": "Giao tiếp rõ ràng quan trọng với tôi hơn việc ai cũng phải là thiên tài."}]}, {"slug": "what-kind-of-work-environment-helps-you-do-your-best-work", "q_en": "What kind of work environment helps you do your best work?", "q_vi": "Môi trường làm việc nào giúp bạn làm việc tốt nhất?", "lines": [{"en": "I do my best work when I have quiet time for deep focus, especially in the morning.", "vi": "Tôi làm việc tốt nhất khi có thời gian yên tĩnh để tập trung sâu, đặc biệt vào buổi sáng."}, {"en": "I also like having flexible hours, since I'm more productive later in the day sometimes.", "vi": "Tôi cũng thích giờ làm linh hoạt, vì đôi khi tôi làm việc hiệu quả hơn vào cuối ngày."}, {"en": "A supportive manager who doesn't micromanage makes a big difference too.", "vi": "Một quản lý biết hỗ trợ và không kiểm soát quá chi tiết cũng tạo ra khác biệt lớn."}]}, {"slug": "how-do-you-feel-about-remote-work", "q_en": "How do you feel about remote work?", "q_vi": "Bạn cảm thấy thế nào về làm việc từ xa?", "lines": [{"en": "I actually enjoy remote work, as long as the team communicates clearly.", "vi": "Tôi thực ra thích làm remote, miễn là team giao tiếp rõ ràng."}, {"en": "I do miss some of the casual conversations you get in an office.", "vi": "Tôi vẫn nhớ những cuộc trò chuyện thoải mái ở văn phòng."}, {"en": "A hybrid setup would probably be my ideal balance.", "vi": "Mô hình hybrid có lẽ là sự cân bằng lý tưởng với tôi."}]}, {"slug": "how-important-is-company-culture-to-you", "q_en": "How important is company culture to you?", "q_vi": "Văn hóa công ty quan trọng với bạn thế nào?", "lines": [{"en": "It's actually one of the top things I consider when choosing a job.", "vi": "Đây thực ra là một trong những yếu tố hàng đầu tôi xem xét khi chọn công việc."}, {"en": "I want to work somewhere that values honesty over just looking busy.", "vi": "Tôi muốn làm việc ở nơi coi trọng sự trung thực hơn là chỉ tỏ ra bận rộn."}, {"en": "A toxic culture can make even a great salary feel not worth it.", "vi": "Một văn hóa độc hại có thể khiến cả mức lương tốt cũng trở nên không đáng."}]}, {"slug": "what-kind-of-manager-do-you-work-best-with", "q_en": "What kind of manager do you work best with?", "q_vi": "Bạn làm việc tốt nhất với kiểu quản lý nào?", "lines": [{"en": "I work best with a manager who gives clear priorities but trusts me with the details.", "vi": "Tôi làm việc tốt nhất với quản lý đưa ra ưu tiên rõ ràng nhưng tin tưởng tôi ở chi tiết."}, {"en": "Regular one-on-ones help me stay aligned without feeling like I'm being watched constantly.", "vi": "Các buổi one-on-one đều đặn giúp tôi giữ đúng hướng mà không cảm thấy bị theo dõi liên tục."}, {"en": "I also appreciate a manager who's honest when something isn't working.", "vi": "Tôi cũng đánh giá cao quản lý thẳng thắn khi có gì đó không ổn."}]}]}, {"id": "le-8", "num": 8, "title": "How do you prioritize multiple projects?", "questions": [{"slug": "how-do-you-prioritize-when-you-have-multiple-projects-at", "q_en": "How do you prioritize when you have multiple projects at once?", "q_vi": "Bạn ưu tiên công việc thế nào khi có nhiều dự án cùng lúc?", "lines": [{"en": "I usually start by checking which project has the closest deadline or biggest impact.", "vi": "Tôi thường bắt đầu bằng việc xem dự án nào có deadline gần nhất hoặc ảnh hưởng lớn nhất."}, {"en": "Then I talk to my manager to confirm my understanding is correct.", "vi": "Sau đó tôi trao đổi với quản lý để xác nhận cách hiểu của mình là đúng."}, {"en": "After that, I block out time in my calendar for each task.", "vi": "Sau đó tôi chặn thời gian trong lịch cho từng việc."}]}, {"slug": "what-do-you-do-when-everything-feels-urgent", "q_en": "What do you do when everything feels urgent?", "q_vi": "Bạn làm gì khi mọi thứ đều có vẻ gấp?", "lines": [{"en": "I try to ask which task would cause the most damage if it were delayed.", "vi": "Tôi cố hỏi việc nào sẽ gây thiệt hại nhiều nhất nếu bị trễ."}, {"en": "That question usually makes the real priority much clearer.", "vi": "Câu hỏi đó thường giúp thấy rõ ưu tiên thật sự hơn nhiều."}, {"en": "If I'm still not sure, I bring it to my manager instead of guessing.", "vi": "Nếu vẫn chưa chắc, tôi sẽ hỏi quản lý thay vì đoán mò."}]}, {"slug": "can-you-give-an-example-of-juggling-multiple-projects", "q_en": "Can you give an example of juggling multiple projects?", "q_vi": "Bạn có thể cho ví dụ về việc xử lý nhiều dự án cùng lúc không?", "lines": [{"en": "Last quarter, I was working on a new feature while also supporting an older system.", "vi": "Quý trước, tôi vừa làm một tính năng mới vừa hỗ trợ một hệ thống cũ."}, {"en": "I spent mornings on the new feature and left support tickets for the afternoon.", "vi": "Tôi dành buổi sáng cho tính năng mới và để các ticket hỗ trợ vào buổi chiều."}, {"en": "It wasn't perfect, but it kept both projects moving forward.", "vi": "Không hoàn hảo, nhưng nó giúp cả hai dự án đều tiến triển."}]}, {"slug": "how-do-you-avoid-burning-out-when-youre-overloaded", "q_en": "How do you avoid burning out when you're overloaded?", "q_vi": "Bạn tránh kiệt sức thế nào khi bị quá tải?", "lines": [{"en": "I try to be honest with my manager as soon as I feel overloaded, instead of staying quiet.", "vi": "Tôi cố thẳng thắn với quản lý ngay khi cảm thấy quá tải, thay vì im lặng chịu đựng."}, {"en": "Taking short breaks during the day also helps me recover faster.", "vi": "Nghỉ ngắn trong ngày cũng giúp tôi hồi phục nhanh hơn."}, {"en": "Saying no to extra requests is hard, but sometimes necessary.", "vi": "Từ chối các yêu cầu thêm không dễ, nhưng đôi khi cần thiết."}]}, {"slug": "do-you-use-any-tools-to-manage-your-tasks", "q_en": "Do you use any tools to manage your tasks?", "q_vi": "Bạn có dùng công cụ nào để quản lý công việc không?", "lines": [{"en": "I keep a simple task board with three columns: to do, in progress, and done.", "vi": "Tôi dùng một bảng công việc đơn giản với ba cột: cần làm, đang làm, và đã xong."}, {"en": "I also block time on my calendar so meetings don't eat into my focus time.", "vi": "Tôi cũng chặn thời gian trong lịch để các buổi họp không chiếm mất thời gian tập trung."}, {"en": "It's not fancy, but it keeps me from forgetting things.", "vi": "Không cầu kỳ, nhưng nó giúp tôi không quên việc."}]}]}, {"id": "le-9", "num": 9, "title": "What are your strengths and weaknesses?", "questions": [{"slug": "what-would-you-say-is-your-biggest-strength", "q_en": "What would you say is your biggest strength?", "q_vi": "Bạn nghĩ điểm mạnh lớn nhất của mình là gì?", "lines": [{"en": "I think my biggest strength is staying calm when something breaks in production.", "vi": "Tôi nghĩ điểm mạnh lớn nhất của tôi là giữ bình tĩnh khi có sự cố ở production."}, {"en": "I focus on fixing the issue first and figuring out the root cause afterward.", "vi": "Tôi tập trung sửa lỗi trước, rồi mới tìm nguyên nhân gốc sau."}, {"en": "That mindset has helped my team a lot during incidents.", "vi": "Cách tư duy đó đã giúp team tôi rất nhiều trong các sự cố."}]}, {"slug": "can-you-give-an-example-of-that-strength-in-action", "q_en": "Can you give an example of that strength in action?", "q_vi": "Bạn có thể cho ví dụ về điểm mạnh đó trong thực tế không?", "lines": [{"en": "Once our payment service went down right before a big sale.", "vi": "Một lần payment service của chúng tôi bị sập ngay trước một đợt sale lớn."}, {"en": "Instead of panicking, I quickly rolled back the last deployment while we investigated.", "vi": "Thay vì hoảng loạn, tôi nhanh chóng rollback bản deploy gần nhất trong lúc chúng tôi điều tra."}, {"en": "That bought us enough time to fix the real issue safely.", "vi": "Điều đó cho chúng tôi đủ thời gian để sửa vấn đề thật một cách an toàn."}]}, {"slug": "what-would-you-say-is-your-biggest-weakness", "q_en": "What would you say is your biggest weakness?", "q_vi": "Bạn nghĩ điểm yếu lớn nhất của mình là gì?", "lines": [{"en": "I sometimes spend too much time trying to make code perfect before shipping it.", "vi": "Đôi khi tôi dành quá nhiều thời gian để làm code hoàn hảo trước khi ship."}, {"en": "I've learned that shipping something good now is often better than something perfect later.", "vi": "Tôi học được rằng ship một thứ tốt ngay bây giờ thường tốt hơn một thứ hoàn hảo sau này."}, {"en": "I'm getting better at knowing when to stop polishing.", "vi": "Tôi đang dần biết rõ hơn khi nào nên dừng việc chỉnh sửa."}]}, {"slug": "how-are-you-working-on-improving-that-weakness", "q_en": "How are you working on improving that weakness?", "q_vi": "Bạn đang cải thiện điểm yếu đó như thế nào?", "lines": [{"en": "I now try to set a rough time limit for myself before starting a task.", "vi": "Giờ tôi cố đặt một giới hạn thời gian sơ bộ cho mình trước khi bắt đầu một việc."}, {"en": "If I go over that limit, I ask a teammate to review what I have so far.", "vi": "Nếu vượt giới hạn đó, tôi nhờ một đồng nghiệp review những gì tôi đã làm."}, {"en": "That extra pair of eyes usually tells me it's good enough to ship.", "vi": "Cặp mắt thứ hai đó thường cho tôi biết là đã đủ tốt để ship."}]}, {"slug": "how-do-your-strengths-help-your-team-specifically", "q_en": "How do your strengths help your team specifically?", "q_vi": "Điểm mạnh của bạn giúp team cụ thể như thế nào?", "lines": [{"en": "Staying calm during incidents means the team can rely on me when things go wrong.", "vi": "Giữ bình tĩnh khi có sự cố nghĩa là team có thể dựa vào tôi khi có chuyện không ổn."}, {"en": "It also sets a tone that helps everyone else stay focused instead of panicking.", "vi": "Nó cũng tạo không khí giúp mọi người giữ tập trung thay vì hoảng loạn."}, {"en": "I think that's more valuable than being the fastest coder in the room.", "vi": "Tôi nghĩ điều đó có giá trị hơn việc là người code nhanh nhất trong phòng."}]}]}, {"id": "le-10", "num": 10, "title": "Tell me about a project you're proud of", "questions": [{"slug": "can-you-tell-me-about-a-project-youre-proud-of", "q_en": "Can you tell me about a project you're proud of?", "q_vi": "Bạn có thể kể về một dự án mà bạn tự hào không?", "lines": [{"en": "I led the migration of our monolithic backend into smaller services.", "vi": "Tôi đã dẫn dắt việc migrate backend monolithic của công ty sang các service nhỏ hơn."}, {"en": "It took about six months and involved three other engineers.", "vi": "Việc này mất khoảng sáu tháng và có ba kỹ sư khác cùng tham gia."}, {"en": "The project reduced our deployment time from an hour to under ten minutes.", "vi": "Dự án này giảm thời gian deploy từ một giờ xuống dưới mười phút."}]}, {"slug": "what-was-your-specific-role-in-that-project", "q_en": "What was your specific role in that project?", "q_vi": "Vai trò cụ thể của bạn trong dự án đó là gì?", "lines": [{"en": "I was responsible for the overall technical plan and splitting the work between the team.", "vi": "Tôi chịu trách nhiệm về kế hoạch kỹ thuật tổng thể và phân chia công việc cho team."}, {"en": "I also handled the trickiest part, which was migrating the payment logic safely.", "vi": "Tôi cũng xử lý phần khó nhất, là migrate logic thanh toán một cách an toàn."}, {"en": "Along the way, I made sure we didn't have any downtime for users.", "vi": "Trong suốt quá trình, tôi đảm bảo người dùng không gặp downtime nào."}]}, {"slug": "what-was-the-biggest-challenge-during-the-project", "q_en": "What was the biggest challenge during the project?", "q_vi": "Thử thách lớn nhất trong dự án là gì?", "lines": [{"en": "The biggest challenge was migrating data without losing anything or causing duplicates.", "vi": "Thử thách lớn nhất là migrate dữ liệu mà không làm mất hay tạo dữ liệu trùng."}, {"en": "We had to run both the old and new systems in parallel for a few weeks.", "vi": "Chúng tôi phải chạy song song cả hệ thống cũ và mới trong vài tuần."}, {"en": "It required a lot of careful testing before we could fully switch over.", "vi": "Việc này cần rất nhiều test kỹ càng trước khi có thể chuyển đổi hoàn toàn."}]}, {"slug": "how-did-you-measure-the-success-of-the-project", "q_en": "How did you measure the success of the project?", "q_vi": "Bạn đo lường thành công của dự án như thế nào?", "lines": [{"en": "We tracked deployment time, error rates, and how often engineers needed to roll back releases.", "vi": "Chúng tôi theo dõi thời gian deploy, tỷ lệ lỗi, và tần suất kỹ sư phải rollback bản phát hành."}, {"en": "All three numbers improved significantly after the migration.", "vi": "Cả ba chỉ số đều cải thiện rõ rệt sau khi migrate."}, {"en": "The team also reported feeling more confident about releasing changes.", "vi": "Team cũng cho biết cảm thấy tự tin hơn khi release thay đổi."}]}, {"slug": "what-would-you-do-differently-if-you-did-it-again", "q_en": "What would you do differently if you did it again?", "q_vi": "Bạn sẽ làm khác gì nếu làm lại dự án này?", "lines": [{"en": "I would probably involve the frontend team earlier in the planning process.", "vi": "Tôi có lẽ sẽ để team frontend tham gia sớm hơn vào quá trình lập kế hoạch."}, {"en": "We ran into a few surprises because some API changes weren't communicated early enough.", "vi": "Chúng tôi gặp vài bất ngờ vì một số thay đổi API không được thông báo sớm."}, {"en": "Better upfront communication would have saved us some rework.", "vi": "Giao tiếp tốt hơn từ đầu sẽ giúp tiết kiệm được vài lần làm lại."}]}]}, {"id": "le-11", "num": 11, "title": "How do you explain technical issues to non-technical people?", "questions": [{"slug": "how-do-you-explain-a-technical-problem-to-a-non-technical", "q_en": "How do you explain a technical problem to a non-technical manager?", "q_vi": "Bạn giải thích một vấn đề kỹ thuật cho quản lý không rành kỹ thuật như thế nào?", "lines": [{"en": "I try to avoid jargon and focus on what the problem actually means for the business.", "vi": "Tôi cố tránh thuật ngữ chuyên môn và tập trung vào ý nghĩa thực tế của vấn đề với việc kinh doanh."}, {"en": "For example, instead of saying the database is locked, I'd say orders are temporarily delayed.", "vi": "Ví dụ, thay vì nói database bị lock, tôi sẽ nói đơn hàng đang bị chậm tạm thời."}, {"en": "That usually helps them understand the impact without needing technical details.", "vi": "Cách đó thường giúp họ hiểu được ảnh hưởng mà không cần chi tiết kỹ thuật."}]}, {"slug": "can-you-give-an-example-of-doing-this", "q_en": "Can you give an example of doing this?", "q_vi": "Bạn có thể cho ví dụ về việc này không?", "lines": [{"en": "Once our system was running slowly because of a database issue.", "vi": "Một lần hệ thống chạy chậm vì vấn đề ở database."}, {"en": "I told my manager that customers might notice a few extra seconds of loading time.", "vi": "Tôi nói với quản lý rằng khách hàng có thể thấy trang tải chậm hơn vài giây."}, {"en": "I also gave a rough estimate of when we expected it to be fixed.", "vi": "Tôi cũng đưa ra một ước lượng sơ bộ về thời điểm dự kiến sửa xong."}]}, {"slug": "how-do-you-handle-it-when-a-manager-wants-a-fix-immediately", "q_en": "How do you handle it when a manager wants a fix immediately?", "q_vi": "Bạn xử lý thế nào khi quản lý muốn sửa ngay lập tức?", "lines": [{"en": "I explain what's realistic and what the tradeoffs would be if we rushed it.", "vi": "Tôi giải thích điều gì thực tế và những đánh đổi nếu làm gấp."}, {"en": "Sometimes a quick fix now means more problems later, and I make that clear.", "vi": "Đôi khi sửa nhanh bây giờ nghĩa là nhiều vấn đề hơn về sau, và tôi nói rõ điều đó."}, {"en": "Most managers appreciate honesty over a false promise.", "vi": "Hầu hết quản lý đánh giá cao sự thành thật hơn một lời hứa không thực tế."}]}, {"slug": "do-you-use-any-tools-or-visuals-to-explain-technical-topics", "q_en": "Do you use any tools or visuals to explain technical topics?", "q_vi": "Bạn có dùng công cụ hay hình ảnh nào để giải thích vấn đề kỹ thuật không?", "lines": [{"en": "Yes, I often use simple diagrams instead of long explanations.", "vi": "Có, tôi thường dùng sơ đồ đơn giản thay vì giải thích dài dòng."}, {"en": "A basic flowchart can make a complex process much easier to follow.", "vi": "Một flowchart cơ bản có thể giúp một quy trình phức tạp dễ theo dõi hơn nhiều."}, {"en": "I've found that people remember visuals better than technical descriptions.", "vi": "Tôi nhận ra mọi người nhớ hình ảnh tốt hơn là mô tả kỹ thuật."}]}, {"slug": "why-do-you-think-this-skill-is-important", "q_en": "Why do you think this skill is important?", "q_vi": "Vì sao bạn nghĩ kỹ năng này quan trọng?", "lines": [{"en": "Because most decisions in a company aren't made by engineers alone.", "vi": "Vì hầu hết quyết định trong công ty không chỉ do kỹ sư đưa ra."}, {"en": "If I can't explain a problem clearly, it's harder to get the support I need.", "vi": "Nếu tôi không giải thích rõ được vấn đề, sẽ khó nhận được sự hỗ trợ mình cần."}, {"en": "Good communication often matters as much as good code.", "vi": "Giao tiếp tốt thường quan trọng không kém gì code tốt."}]}]}, {"id": "le-12", "num": 12, "title": "What are your salary expectations?", "questions": [{"slug": "what-are-your-salary-expectations-for-this-role", "q_en": "What are your salary expectations for this role?", "q_vi": "Bạn mong muốn mức lương thế nào cho vị trí này?", "lines": [{"en": "Based on my research and experience level, I have a specific range in mind that reflects the market rate for this role.", "vi": "Dựa trên tìm hiểu và mức kinh nghiệm của tôi, tôi có một khoảng lương cụ thể phản ánh mức thị trường cho vị trí này."}, {"en": "That said, I'm open to discussing the full package, including benefits.", "vi": "Tuy vậy, tôi sẵn sàng trao đổi về toàn bộ package, bao gồm cả phúc lợi."}, {"en": "I'm more focused on finding the right fit than a specific number.", "vi": "Tôi quan tâm việc tìm được sự phù hợp hơn là một con số cụ thể."}]}, {"slug": "is-salary-the-most-important-factor-for-you", "q_en": "Is salary the most important factor for you?", "q_vi": "Lương có phải yếu tố quan trọng nhất với bạn không?", "lines": [{"en": "It's important, but it's not the only thing I consider.", "vi": "Nó quan trọng, nhưng không phải điều duy nhất tôi xem xét."}, {"en": "Growth opportunities and team culture matter just as much to me.", "vi": "Cơ hội phát triển và văn hóa team cũng quan trọng với tôi không kém."}, {"en": "A slightly lower salary wouldn't stop me from taking a great opportunity.", "vi": "Một mức lương thấp hơn chút cũng không ngăn tôi nhận một cơ hội tốt."}]}, {"slug": "do-you-have-any-questions-for-us", "q_en": "Do you have any questions for us?", "q_vi": "Bạn có câu hỏi gì cho chúng tôi không?", "lines": [{"en": "Yes, actually. Could you tell me more about how the team measures success?", "vi": "Có, thực ra là có. Anh/chị có thể chia sẻ thêm về cách team đo lường thành công không?"}, {"en": "I'm also curious about what a typical onboarding process looks like here.", "vi": "Tôi cũng muốn biết quy trình onboarding ở đây thường như thế nào."}, {"en": "And if possible, I'd love to know more about growth opportunities in this role.", "vi": "Và nếu được, tôi muốn biết thêm về cơ hội phát triển ở vị trí này."}]}, {"slug": "when-would-you-be-able-to-start", "q_en": "When would you be able to start?", "q_vi": "Khi nào bạn có thể bắt đầu?", "lines": [{"en": "I would need to give my current employer two weeks' notice.", "vi": "Tôi cần báo trước hai tuần cho công ty hiện tại."}, {"en": "After that, I'd be ready to start immediately.", "vi": "Sau đó tôi có thể bắt đầu ngay."}, {"en": "I'm also flexible if you need a bit more time to finish the hiring process.", "vi": "Tôi cũng linh động nếu công ty cần thêm thời gian để hoàn tất quy trình tuyển dụng."}]}, {"slug": "is-there-anything-else-youd-like-us-to-know-about-you", "q_en": "Is there anything else you'd like us to know about you?", "q_vi": "Bạn có điều gì khác muốn chúng tôi biết về bạn không?", "lines": [{"en": "I just want to add that I'm genuinely excited about this opportunity.", "vi": "Tôi chỉ muốn nói thêm là tôi thực sự hào hứng với cơ hội này."}, {"en": "I think my experience with backend systems lines up well with what you're looking for.", "vi": "Tôi nghĩ kinh nghiệm của tôi với hệ thống backend khá phù hợp với điều công ty đang tìm kiếm."}, {"en": "I'm looking forward to hearing about the next steps.", "vi": "Tôi mong được biết thêm về các bước tiếp theo."}]}]}, {"id": "le-13", "num": 13, "title": "Explain your approach in a live coding interview", "questions": [{"slug": "do-you-have-any-questions-before-you-start-coding", "q_en": "Do you have any questions before you start coding?", "q_vi": "Bạn có câu hỏi nào trước khi bắt đầu code không?", "lines": [{"en": "Yes. First, let me restate it: I need to find two numbers in the array that add up to the target.", "vi": "Có. Trước tiên, để tôi nhắc lại đề: tôi cần tìm hai số trong mảng có tổng bằng target."}, {"en": "Can the array contain negative numbers or duplicates?", "vi": "Mảng có thể chứa số âm hoặc số trùng nhau không?"}, {"en": "And if there's no valid pair, should I return an empty result or throw an error?", "vi": "Và nếu không có cặp nào hợp lệ, tôi nên trả về kết quả rỗng hay báo lỗi?"}]}, {"slug": "how-would-you-approach-this-problem", "q_en": "How would you approach this problem?", "q_vi": "Bạn sẽ tiếp cận bài toán này thế nào?", "lines": [{"en": "My first idea is the brute-force way: check every possible pair of numbers.", "vi": "Ý tưởng đầu tiên của tôi là cách brute-force: kiểm tra mọi cặp số có thể."}, {"en": "That works, but it runs in O of n squared time, so it gets slow for large inputs.", "vi": "Cách đó chạy được, nhưng độ phức tạp là O(n²), nên sẽ chậm khi dữ liệu đầu vào lớn."}, {"en": "I think I can do better with a hash map, so let me talk through that.", "vi": "Tôi nghĩ có thể làm tốt hơn với hash map, để tôi trình bày cách đó nhé."}]}, {"slug": "can-you-explain-your-solution-as-you-code", "q_en": "Can you explain your solution as you code?", "q_vi": "Bạn có thể vừa code vừa giải thích lời giải không?", "lines": [{"en": "Sure. I'll loop through the array once and keep a hash map of the numbers I've already seen.", "vi": "Được. Tôi sẽ duyệt mảng một lần và giữ một hash map chứa các số đã gặp."}, {"en": "For each number, I check if the target minus that number is already in the map.", "vi": "Với mỗi số, tôi kiểm tra xem target trừ đi số đó đã có trong map chưa."}, {"en": "If it is, I've found the pair, so I return both indices right away.", "vi": "Nếu có thì tôi đã tìm ra cặp số, nên tôi trả về hai chỉ số đó ngay."}]}, {"slug": "what-is-the-time-and-space-complexity-of-your-solution", "q_en": "What is the time and space complexity of your solution?", "q_vi": "Độ phức tạp thời gian và bộ nhớ của lời giải là bao nhiêu?", "lines": [{"en": "The time complexity is O of n, because I only go through the array once.", "vi": "Độ phức tạp thời gian là O(n), vì tôi chỉ duyệt mảng một lần."}, {"en": "The space complexity is also O of n, since in the worst case the map stores every number.", "vi": "Độ phức tạp bộ nhớ cũng là O(n), vì trong trường hợp xấu nhất map lưu mọi số."}, {"en": "So I'm trading a little extra memory for a much faster solution.", "vi": "Tức là tôi đánh đổi thêm một chút bộ nhớ để có lời giải nhanh hơn nhiều."}]}, {"slug": "how-would-you-test-your-code", "q_en": "How would you test your code?", "q_vi": "Bạn sẽ test code của mình thế nào?", "lines": [{"en": "I'd start with a simple case, like a small array where the answer is obvious.", "vi": "Tôi sẽ bắt đầu với một trường hợp đơn giản, như một mảng nhỏ có đáp án rõ ràng."}, {"en": "Then I'd check the edge cases: an empty array, no valid pair, and duplicate numbers.", "vi": "Sau đó tôi kiểm tra các edge case: mảng rỗng, không có cặp hợp lệ, và số bị trùng."}, {"en": "Finally, I'd try a very large input to make sure the performance holds up.", "vi": "Cuối cùng, tôi thử với dữ liệu đầu vào rất lớn để chắc hiệu năng vẫn ổn."}]}]}, {"id": "le-14", "num": 14, "title": "Design a URL shortener", "questions": [{"slug": "how-would-you-start-designing-a-url-shortener", "q_en": "How would you start designing a URL shortener?", "q_vi": "Bạn sẽ bắt đầu thiết kế một dịch vụ rút gọn link như thế nào?", "lines": [{"en": "First, I'd clarify the requirements before drawing anything.", "vi": "Trước tiên, tôi sẽ làm rõ yêu cầu trước khi vẽ bất cứ thứ gì."}, {"en": "The main features are creating a short link and redirecting users to the original URL.", "vi": "Hai chức năng chính là tạo link ngắn và chuyển hướng người dùng về URL gốc."}, {"en": "I'd also ask about scale, for example how many new links we expect per day.", "vi": "Tôi cũng sẽ hỏi về quy mô, ví dụ mỗi ngày dự kiến có bao nhiêu link mới."}]}, {"slug": "how-would-you-generate-the-short-codes", "q_en": "How would you generate the short codes?", "q_vi": "Bạn sẽ tạo mã rút gọn như thế nào?", "lines": [{"en": "I'd give each new URL a unique ID from a counter and encode it in base sixty-two.", "vi": "Tôi sẽ cấp cho mỗi URL mới một ID duy nhất từ bộ đếm rồi mã hoá nó sang base62."}, {"en": "Seven characters in base sixty-two give us more than three trillion unique codes.", "vi": "Bảy ký tự base62 cho chúng ta hơn ba nghìn tỷ mã khác nhau."}, {"en": "Random codes also work, but then we have to check for collisions.", "vi": "Mã ngẫu nhiên cũng được, nhưng khi đó phải kiểm tra trùng mã."}]}, {"slug": "how-would-you-store-the-data", "q_en": "How would you store the data?", "q_vi": "Bạn sẽ lưu dữ liệu như thế nào?", "lines": [{"en": "The data model is simple: a short code, the original URL, and a created date.", "vi": "Mô hình dữ liệu rất đơn giản: mã rút gọn, URL gốc và ngày tạo."}, {"en": "Since we mostly look up by key, a key-value store or a NoSQL database fits well.", "vi": "Vì chủ yếu tra cứu theo khoá, một key-value store hoặc database NoSQL là phù hợp."}, {"en": "Reads are much more frequent than writes, so I'd design for fast lookups.", "vi": "Lượt đọc nhiều hơn lượt ghi rất nhiều, nên tôi sẽ thiết kế để tra cứu thật nhanh."}]}, {"slug": "how-would-you-handle-a-lot-of-traffic", "q_en": "How would you handle a lot of traffic?", "q_vi": "Bạn sẽ xử lý lượng truy cập lớn như thế nào?", "lines": [{"en": "I'd put a cache like Redis in front of the database for popular links.", "vi": "Tôi sẽ đặt một lớp cache như Redis trước database cho các link phổ biến."}, {"en": "Most traffic goes to a small number of links, so the cache hit rate should be high.", "vi": "Phần lớn truy cập dồn vào một số ít link, nên tỉ lệ cache hit sẽ cao."}, {"en": "Then I'd add more application servers behind a load balancer as traffic grows.", "vi": "Sau đó tôi sẽ thêm application server phía sau load balancer khi lượng truy cập tăng."}]}, {"slug": "what-trade-offs-would-you-mention", "q_en": "What trade-offs would you mention?", "q_vi": "Bạn sẽ nêu những đánh đổi nào?", "lines": [{"en": "A 301 redirect is faster because browsers cache it, but we lose click analytics.", "vi": "Redirect 301 nhanh hơn vì trình duyệt cache lại, nhưng ta mất dữ liệu thống kê lượt click."}, {"en": "A 302 redirect costs a bit more, but every click comes back to our servers.", "vi": "Redirect 302 tốn hơn một chút, nhưng mọi lượt click đều quay về server của mình."}, {"en": "I'd ask the interviewer which matters more: speed or tracking.", "vi": "Tôi sẽ hỏi người phỏng vấn điều gì quan trọng hơn: tốc độ hay theo dõi lượt click."}]}]}, {"id": "le-15", "num": 15, "title": "Do you have any questions for us?", "questions": [{"slug": "do-you-have-any-questions-for-us-2", "q_en": "Do you have any questions for us?", "q_vi": "Bạn có câu hỏi nào cho chúng tôi không?", "lines": [{"en": "Yes, thank you. I'd like to know what a typical week looks like for this team.", "vi": "Có, cảm ơn anh/chị. Tôi muốn biết một tuần làm việc bình thường của team diễn ra như thế nào."}, {"en": "How much time goes to new features, and how much goes to maintenance?", "vi": "Bao nhiêu thời gian dành cho tính năng mới, và bao nhiêu dành cho bảo trì?"}, {"en": "That would help me understand where I could contribute the most.", "vi": "Điều đó giúp tôi hiểu mình có thể đóng góp nhiều nhất ở đâu."}]}, {"slug": "what-would-you-like-to-know-about-the-team", "q_en": "What would you like to know about the team?", "q_vi": "Bạn muốn biết gì về team?", "lines": [{"en": "How big is the team, and how do you usually split the work?", "vi": "Team có bao nhiêu người, và thường chia việc như thế nào?"}, {"en": "I'm also curious about how code reviews work here.", "vi": "Tôi cũng tò mò về cách review code ở đây."}, {"en": "For example, how long does it usually take for a pull request to get merged?", "vi": "Ví dụ, một pull request thường mất bao lâu để được merge?"}]}, {"slug": "is-there-anything-you-want-to-ask-about-growth", "q_en": "Is there anything you want to ask about growth?", "q_vi": "Bạn có muốn hỏi gì về con đường phát triển không?", "lines": [{"en": "Yes. What does success look like in this role after six months?", "vi": "Có. Sau sáu tháng, thế nào thì được coi là thành công ở vị trí này?"}, {"en": "And how do engineers here usually grow, for example toward senior or tech lead?", "vi": "Và kỹ sư ở đây thường phát triển ra sao, ví dụ lên senior hay tech lead?"}, {"en": "I'd also like to know if there's a budget for courses or conferences.", "vi": "Tôi cũng muốn biết công ty có ngân sách cho khoá học hay hội thảo không."}]}, {"slug": "what-do-you-want-to-know-about-our-tech-stack", "q_en": "What do you want to know about our tech stack?", "q_vi": "Bạn muốn biết gì về tech stack của chúng tôi?", "lines": [{"en": "I saw that you use Kubernetes and Go. Are you planning any big changes?", "vi": "Tôi thấy công ty dùng Kubernetes và Go. Sắp tới có kế hoạch thay đổi lớn nào không?"}, {"en": "Is there any technical debt the team is working to pay down?", "vi": "Team có đang xử lý khoản nợ kỹ thuật nào không?"}, {"en": "That tells me a lot about the challenges I'd face in the first few months.", "vi": "Điều đó cho tôi biết khá nhiều về những thử thách tôi sẽ gặp trong vài tháng đầu."}]}, {"slug": "any-final-questions-before-we-finish", "q_en": "Any final questions before we finish?", "q_vi": "Còn câu hỏi nào cuối cùng trước khi kết thúc không?", "lines": [{"en": "Just one: what are the next steps in the hiring process?", "vi": "Chỉ một câu thôi: các bước tiếp theo trong quy trình tuyển dụng là gì?"}, {"en": "And is there anything about my background that you'd like me to clarify?", "vi": "Và có điều gì trong kinh nghiệm của tôi mà anh/chị muốn tôi làm rõ thêm không?"}, {"en": "Thank you for your time. I really enjoyed this conversation.", "vi": "Cảm ơn anh/chị đã dành thời gian. Tôi thật sự thích cuộc trò chuyện này."}]}]}, {"id": "le-16", "num": 16, "title": "A recruiter screening call", "questions": [{"slug": "can-you-tell-me-a-little-about-your-current-situation", "q_en": "Can you tell me a little about your current situation?", "q_vi": "Bạn có thể kể một chút về tình hình hiện tại của mình không?", "lines": [{"en": "Sure. I'm a backend developer with five years of experience, currently at a fintech company in Hanoi.", "vi": "Vâng. Tôi là backend developer với năm năm kinh nghiệm, hiện đang làm ở một công ty fintech tại Hà Nội."}, {"en": "I'm happy there, but I'm looking for a role in a bigger international team.", "vi": "Tôi làm việc ở đó vẫn ổn, nhưng muốn tìm một vị trí trong team quốc tế lớn hơn."}, {"en": "That's why this position caught my attention.", "vi": "Đó là lý do vị trí này thu hút tôi."}]}, {"slug": "what-is-your-notice-period", "q_en": "What is your notice period?", "q_vi": "Thời gian báo trước khi nghỉ việc của bạn là bao lâu?", "lines": [{"en": "My notice period is thirty days, according to my current contract.", "vi": "Theo hợp đồng hiện tại, tôi cần báo trước ba mươi ngày."}, {"en": "So I could start about one month after signing the offer.", "vi": "Vì vậy tôi có thể bắt đầu khoảng một tháng sau khi ký offer."}, {"en": "If needed, I can discuss a shorter handover with my manager.", "vi": "Nếu cần, tôi có thể trao đổi với quản lý để rút ngắn thời gian bàn giao."}]}, {"slug": "what-are-your-salary-expectations", "q_en": "What are your salary expectations?", "q_vi": "Mức lương mong muốn của bạn là bao nhiêu?", "lines": [{"en": "Based on my experience and the market, I'm looking for around two thousand five hundred US dollars a month.", "vi": "Dựa trên kinh nghiệm và mặt bằng thị trường, tôi mong muốn khoảng hai nghìn năm trăm đô la Mỹ mỗi tháng."}, {"en": "That said, I'm flexible and would like to understand the full package first.", "vi": "Dù vậy, tôi khá linh hoạt và muốn hiểu toàn bộ gói đãi ngộ trước."}, {"en": "Could you share the budget range for this role?", "vi": "Anh/chị có thể chia sẻ khoảng ngân sách cho vị trí này không?"}]}, {"slug": "are-you-open-to-relocation-or-working-remotely", "q_en": "Are you open to relocation or working remotely?", "q_vi": "Bạn có sẵn sàng chuyển nơi ở hoặc làm việc từ xa không?", "lines": [{"en": "I'm open to relocating for the right opportunity, as long as visa support is provided.", "vi": "Tôi sẵn sàng chuyển nơi ở nếu cơ hội phù hợp, miễn là công ty hỗ trợ visa."}, {"en": "If the role is remote, I'm comfortable working with a team in a different time zone.", "vi": "Nếu là vị trí remote, tôi quen làm việc với team ở múi giờ khác."}, {"en": "For the past two years, I've joined daily standups with colleagues in Europe.", "vi": "Hai năm qua, tôi họp standup hằng ngày với đồng nghiệp ở châu Âu."}]}, {"slug": "do-you-need-a-work-visa", "q_en": "Do you need a work visa?", "q_vi": "Bạn có cần visa làm việc không?", "lines": [{"en": "Yes, I would need visa sponsorship to work in another country.", "vi": "Có, tôi sẽ cần công ty bảo lãnh visa để làm việc ở nước khác."}, {"en": "I already have my documents ready, including my degree and employment certificates.", "vi": "Tôi đã chuẩn bị sẵn giấy tờ, gồm bằng đại học và giấy xác nhận công việc."}, {"en": "I'm happy to provide anything else you need for the application.", "vi": "Tôi sẵn sàng cung cấp thêm bất cứ giấy tờ nào cần cho hồ sơ."}]}]}]};
